def write_complete(path: Path, text: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(text.lstrip(), encoding="utf-8", newline="\n")
    ast.parse(path.read_text(encoding="utf-8"), filename=str(path))
    print(f"[OK] FULL REPLACEMENT: {path.resolve()}")

def validate_current_repository() -> None:
    missing = [str(p) for p in (UPSTREAM, UPSTREAM_TEST) if not p.is_file()]
    if missing:
        raise RuntimeError("Required certified files missing: " + ", ".join(missing))
    if str(ROOT) not in sys.path:
        sys.path.insert(0, str(ROOT))
    module = importlib.import_module("qseries_v2.oracle_memory.oracle_memory_certified_market_behavior_cross_market_dependency_memory_077")
    if getattr(module, "SCHEMA_VERSION", None) != "OML-077":
        raise RuntimeError("OML-077 SCHEMA_VERSION mismatch")
    if getattr(module, "ENGINE_ID", None) != "OML-077":
        raise RuntimeError("OML-077 ENGINE_ID mismatch")
    fields=set(module.OracleMemoryCertifiedMarketBehaviorCrossMarketDependencyMemory077.__dataclass_fields__)
    required={"dependencies","dependency_memory_ready","downstream_freeze_certification_authorized","certification_hash","read_only"}
    absent=sorted(required-fields)
    if absent:
        raise RuntimeError("OML-077 dataclass fields missing: "+", ".join(absent))

def main() -> int:
    print("=" * 48)
    print(" OML-078 REPOSITORY-VERIFIED INSTALLER")
    print(" FINAL FREEZE READINESS CERTIFICATION GATE")
    print("=" * 48)
    print("[BOOT] Revision: EXACT_CURRENT_REPOSITORY_OML_077_STRICT_NONEMPTY_INVENTORY")
    try:
        validate_current_repository()
        print("[OK] Current OML-077 interface inspected")
        tracked={p:p.read_bytes() for p in (UPSTREAM,UPSTREAM_TEST)}
        write_complete(PRODUCTION, PRODUCTION_SOURCE)
        write_complete(TEST, TEST_SOURCE)
        export="from .oracle_memory_final_freeze_readiness_certification_gate_078 import *"
        current=INIT.read_text(encoding="utf-8") if INIT.exists() else ""
        if export not in current.splitlines():
            if current and not current.endswith("\n"):
                current += "\n"
            current += export + "\n"
            INIT.write_text(current, encoding="utf-8", newline="\n")
            print(f"[OK] PACKAGE UPDATED: {INIT.resolve()}")
        else:
            print(f"[OK] PACKAGE EXPORT PRESENT: {INIT.resolve()}")
        completed=subprocess.run([sys.executable,str(TEST)],cwd=ROOT,check=False)
        if completed.returncode:
            raise RuntimeError(f"OML-078 test failed with exit code {completed.returncode}")
        for p,before in tracked.items():
            if p.read_bytes()!=before:
                raise RuntimeError(f"Certified upstream changed: {p}")
        print("[PASS] Complete OML-078 production replacement installed")
        print("[PASS] Complete deterministic standalone test installed")
        print("[PASS] Zero-byte Oracle Memory package files rejected")
        print("[PASS] Exact legacy OML-001 empty test excluded")
        print("[PASS] Unknown empty OML tests rejected")
        print("[PASS] Oracle Terminal separation preserved")
        print("[PASS] Active capabilities remained disabled")
        print("[DONE] OML-078 FINAL FREEZE READINESS CERTIFIED")
        return 0
    except (RuntimeError,SyntaxError,ImportError,AttributeError,KeyError,TypeError,ValueError) as exc:
        print(f"[ERROR] {exc}")
        return 1

if __name__ == "__main__":
    raise SystemExit(main())
